package com.eurobuddha.minimacore.chat;

import com.eurobuddha.minimacore.i18n.Language;
import static com.eurobuddha.minimacore.i18n.R.string.*;

/** Explicit chat failures only. Never use for user content, names, addresses or filenames.
 * Reuses Parlons SystemMessages' fixed lookup, literal captures and bounded diagnostic recursion.
 * Generated by tools/localization/generate.cjs from localization/chat-errors.json. */
public final class ChatMessages {
    private ChatMessages() {}
    public static CharSequence error(Throwable error) {
        if (error == null) return Language.msg(l10n_chat_error_operation_failed);
        return message(error.getMessage() == null ? error.toString() : error.getMessage());
    }
    public static CharSequence message(String value) { return message(value,0); }
    private static CharSequence message(String value,int depth) {
        if (value == null) return "";
        if (depth >= 8) return value;
        switch(value) {
            case "could not open image": return Language.msg(l10n_chat_error_open_image);
            case "could not read image": return Language.msg(l10n_chat_error_read_image);
            case "MediaStore refused": return Language.msg(l10n_chat_error_save_image);
            case "Parlons transport still starting - try again in a moment": return Language.msg(l10n_chat_error_transport_starting);
            case "Parlons transport not running": return Language.msg(l10n_chat_error_transport_stopped);
            case "media service not set": return Language.msg(l10n_chat_error_media_unavailable);
            case "empty media": return Language.msg(l10n_chat_error_empty_media);
            case "not a MAX# address": return Language.msg(l10n_chat_error_not_max_address);
            case "malformed MAX# address": return Language.msg(l10n_chat_error_malformed_max_address);
            case "send interrupted": return Language.msg(l10n_chat_error_send_interrupted);
            case "send interrupted before fallback": return Language.msg(l10n_chat_error_send_interrupted_before_fallback);
            case "node stopped": return Language.msg(l10n_chat_error_node_stopped);
            case "lane closed": return Language.msg(l10n_chat_error_lane_closed);
            default: break;
        }
        for(int i=0;i<PATTERNS.length;i++) {
            java.util.regex.Matcher match=PATTERNS[i].matcher(value);
            if(!match.matches())continue;
            Object[] arguments=new Object[match.groupCount()];
            for(int j=0;j<arguments.length;j++) {
                String literal=match.group(j+1);
                arguments[j]=DIAGNOSTIC[i][j] ? message(literal,depth+1) : literal;
            }
            return Language.msg(RESOURCES[i],arguments);
        }
        return value;
    }
    private static final java.util.regex.Pattern[] PATTERNS={
        java.util.regex.Pattern.compile("media\\ over\\ (-?[0-9]+)\\ bytes"),
        java.util.regex.Pattern.compile("Maxima\\ mesh\\ supports\\ files\\ up\\ to\\ (-?[0-9]+)\\ MB\\.\\ This\\ file\\ is\\ (-?[0-9]+(?:\\.[0-9]+)?)\\ MB\\ —\\ host\\ it\\ on\\ a\\ server\\ \\(SFTP/IPFS/GitHub\\)\\ or\\ compress\\ it\\ first\\."),
        java.util.regex.Pattern.compile("no\\ reachable\\ address\\ for\\ ((?s:.*))\\ \\(peer\\ not\\ registered\\ at\\ that\\ MLS,\\ or\\ we\\ share\\ no\\ relay\\)"),
        java.util.regex.Pattern.compile("couldn't\\ reach\\ ((?s:.*))\\ on\\ any\\ known\\ relay"),
        java.util.regex.Pattern.compile("anchor\\ directory\\ failed:\\ ((?s:.*))"),
        java.util.regex.Pattern.compile("MaximaPackage\\ too\\ big:\\ (-?[0-9]+)\\ >\\ (-?[0-9]+)\\ \\(peer\\ would\\ reply\\ TOOBIG\\)")
    };
    private static final int[] RESOURCES={l10n_chat_error_media_over,l10n_chat_error_mesh_limit,l10n_chat_error_no_reachable_address,l10n_chat_error_unreachable_relay,l10n_chat_error_anchor_directory,l10n_chat_error_package_too_big};
    private static final boolean[][] DIAGNOSTIC={{false},{false,false},{false},{false},{false},{false,false}};
}
